<?php
/** How large language models work: tokens, next-token prediction, transformers and attention, training, context, limits. */

return [
    'id' => 'llm-base', 'family' => 'llm', 'after' => 'ai-base', 'categories' => ['ai'],
    'title' => L('LLM: come funzionano', 'LLMs: how they work'), 'short' => L('LLM', 'LLMs'), 'level' => L('Base', 'Basics'),
    'desc' => L('Che cosa c’è dentro un modello linguistico: token, previsione della parola successiva, transformer e attenzione, addestramento, finestra di contesto, temperatura e allucinazioni.', 'What is inside a language model: tokens, next-token prediction, transformers and attention, training, context window, temperature and hallucinations.'),
    'lessons' => [
        lesson('tokens', L('Token e previsione del prossimo token', 'Tokens and next-token prediction'), [
            P('Un **LLM** (Large Language Model) non legge lettere né parole intere: il testo viene spezzato in **token**, pezzi di parola presi da un vocabolario fisso (in inglese un token vale in media circa 3/4 di parola; l’italiano ne usa un po’ di più). Ogni token diventa un numero, e il modello lavora solo con numeri.', 'An **LLM** (Large Language Model) does not read letters or whole words: text is split into **tokens**, word pieces taken from a fixed vocabulary (in English a token is on average about 3/4 of a word; Italian uses a few more). Each token becomes a number, and the model works only with numbers.'),
            C('"Fucina insegna"  →  ["F", "uc", "ina", " ins", "egna"]  →  [37, 1504, 2259, 1286, 9821]', 'text'),
            P('Il compito di base è uno solo: dato il testo fin qui, **prevedere il token successivo**. Il modello produce una probabilità per ogni token del vocabolario, ne sceglie uno, lo aggiunge al testo e ricomincia. Le risposte lunghe nascono così, un token alla volta (**generazione autoregressiva**).', 'The basic task is just one: given the text so far, **predict the next token**. The model produces a probability for every token in the vocabulary, picks one, appends it to the text and starts again. Long answers are born this way, one token at a time (**autoregressive generation**).'),
        ], [
            Q('t1', L('Che cos’è un token?', 'What is a token?'), [L('Un pezzo di testo preso da un vocabolario fisso', 'A piece of text from a fixed vocabulary'), L('Sempre una parola intera', 'Always a whole word'), L('Una singola lettera, sempre', 'A single letter, always'), L('Una frase completa', 'A complete sentence')], 0, L('Spesso pezzi di parola.', 'Often word pieces.')),
            Q('t2', L('Qual è il compito di base di un LLM?', 'What is an LLM’s basic task?'), [L('Prevedere il token successivo', 'Predicting the next token'), L('Cercare la risposta su Google', 'Searching Google for the answer'), L('Copiare un testo dal database', 'Copying text from a database'), L('Tradurre solo in inglese', 'Translating into English only')], 0, L('Un token alla volta.', 'One token at a time.')),
            Q('t3', L('Come nasce una risposta lunga?', 'How is a long answer produced?'), [L('Aggiungendo un token alla volta e ripetendo', 'By adding one token at a time and repeating'), L('Tutta in un colpo solo', 'All in one go'), L('Da un modello per ogni frase', 'From one model per sentence'), L('Leggendola da un file', 'By reading it from a file')], 0, L('Generazione autoregressiva.', 'Autoregressive generation.')),
        ], task('text', L('Descrivi il ciclo di generazione in tre passi, uno per riga numerati da `1.` a `3.`: probabilità, scelta del token, aggiunta al testo.', 'Describe the generation loop in three steps, one per line numbered `1.` to `3.`: probabilities, picking the token, appending it to the text.'), "1. \n2. \n3. ", [re('^1\.\s*.*(probabil)', L('Prima le probabilità', 'First the probabilities')), re('^2\.\s*.*(scegl|scelt|pick|choose|select)', L('Poi la scelta', 'Then the choice')), re('^3\.\s*.*(aggiung|append|add)', L('Infine l’aggiunta', 'Finally appending'))], '', "1. calcola la probabilità di ogni token\n2. sceglie un token\n3. lo aggiunge al testo e ricomincia"), [
            dOrder(pSort(), [L('Il testo diventa token', 'Text becomes tokens'), L('I token diventano numeri', 'Tokens become numbers'), L('Il modello calcola le probabilità', 'The model computes probabilities'), L('Si sceglie il prossimo token', 'The next token is picked'), L('Il token si aggiunge e si ripete', 'The token is appended and it repeats')], L('Dal testo al testo.', 'From text to text.')),
            dFlash(pFlash(), [[L('Un LLM lavora internamente con numeri', 'An LLM works internally with numbers'), true], [L('Un token è sempre una parola intera', 'A token is always a whole word'), false], [L('La risposta si genera un token alla volta', 'The answer is generated one token at a time'), true], [L('L’italiano usa sempre meno token dell’inglese', 'Italian always uses fewer tokens than English'), false]], L('Token dopo token.', 'Token after token.')),
        ]),
        lesson('transformer', L('Embedding, transformer e attenzione', 'Embeddings, transformers and attention'), [
            P('Ogni token viene trasformato in un **embedding**: un vettore di migliaia di numeri che ne rappresenta il significato. Parole simili hanno vettori vicini: “gatto” è più vicino a “cane” che a “frigorifero”.', 'Each token is turned into an **embedding**: a vector of thousands of numbers representing its meaning. Similar words have nearby vectors: “cat” is closer to “dog” than to “fridge”.'),
            P('Quasi tutti gli LLM sono **transformer** (architettura del 2017). Il cuore è il meccanismo di **attenzione**: per ogni token il modello decide quanto “guardare” ciascuno degli altri token del contesto. In “Il gatto non salta sul tavolo perché **è** troppo alto”, l’attenzione collega “è” a “tavolo”. Decine di strati di attenzione e reti neurali, uno sopra l’altro, costruiscono una comprensione sempre più astratta.', 'Almost all LLMs are **transformers** (a 2017 architecture). The core is the **attention** mechanism: for each token the model decides how much to “look at” each of the other tokens in the context. In “The cat does not jump on the table because **it** is too high”, attention links “it” to “table”. Dozens of attention and neural network layers, stacked, build an increasingly abstract understanding.'),
            Tip('I **parametri** (pesi) sono i numeri che il modello impara: da pochi miliardi nei modelli locali a migliaia di miliardi nei più grandi. Più parametri non vuol dire sempre migliore: contano anche dati e addestramento.', '**Parameters** (weights) are the numbers the model learns: from a few billion in local models to thousands of billions in the largest. More parameters does not always mean better: data and training matter too.'),
        ], [
            Q('e1', L('Che cos’è un embedding?', 'What is an embedding?'), [L('Un vettore di numeri che rappresenta il significato', 'A vector of numbers representing meaning'), L('Un’immagine del token', 'A picture of the token'), L('Il nome del modello', 'The model’s name'), L('Un file di configurazione', 'A configuration file')], 0, L('Significati simili, vettori vicini.', 'Similar meanings, nearby vectors.')),
            Q('e2', L('Che cosa fa l’attenzione?', 'What does attention do?'), [L('Pesa quanto ogni token guarda gli altri', 'Weighs how much each token looks at others'), L('Tiene sveglio il modello', 'Keeps the model awake'), L('Cancella i token inutili dal testo', 'Deletes useless tokens from text'), L('Conta le parole', 'Counts words')], 0, L('Collega le parti del contesto.', 'Links parts of the context.')),
            Q('e3', L('Che cosa sono i parametri di un modello?', 'What are a model’s parameters?'), [L('I numeri appresi durante l’addestramento', 'The numbers learned during training'), L('Le domande degli utenti', 'Users’ questions'), L('Le opzioni del menu', 'The menu options'), L('I server che lo ospitano', 'The servers hosting it')], 0, L('Detti anche pesi.', 'Also called weights.')),
        ], task('text', L('Nella frase “La torta non entra nella scatola perché è troppo grande”, a quale parola si riferisce “è”? Scrivi la parola e una riga che spieghi il ruolo dell’**attenzione**.', 'In the sentence “The cake does not fit in the box because it is too big”, which word does “it” refer to? Write the word and a line explaining the role of **attention**.'), '', [re('torta|cake', L('La parola giusta', 'The right word')), re('attenzion|attention', L('Parla di attenzione', 'Mentions attention'))], '', "torta\nL’attenzione collega “è” a “torta” guardando il resto della frase."), [
            dMatch(pMatch(), [['Token', L('Pezzo di testo', 'Piece of text')], ['Embedding', L('Vettore di significato', 'Meaning vector')], [L('Attenzione', 'Attention'), L('Collega i token tra loro', 'Links tokens together')], [L('Parametri', 'Parameters'), L('Numeri appresi', 'Learned numbers')], ['Transformer', L('L’architettura degli LLM', 'The LLM architecture')]], L('Il motore dentro il modello.', 'The engine inside the model.')),
            dFlash(pFlash(), [[L('Il transformer è stato presentato nel 2017', 'The transformer was introduced in 2017'), true], [L('Più parametri garantiscono sempre un modello migliore', 'More parameters always guarantee a better model'), false], [L('Parole simili hanno embedding vicini', 'Similar words have nearby embeddings'), true], [L('L’attenzione guarda solo il token precedente', 'Attention looks only at the previous token'), false]], L('Vettori e attenzione.', 'Vectors and attention.')),
        ]),
        lesson('training', L('Come si addestra un LLM', 'How an LLM is trained'), [
            P('Il **pre-addestramento** è la fase più costosa: il modello legge migliaia di miliardi di token (web, libri, codice) e impara a prevedere il token successivo, correggendo i pesi a ogni errore. Ne esce un modello che “sa” molte cose ma completa testi, non segue istruzioni.', '**Pre-training** is the most expensive phase: the model reads thousands of billions of tokens (web, books, code) and learns to predict the next token, adjusting its weights at every mistake. The result is a model that “knows” many things but completes text, it does not follow instructions.'),
            P('Poi arriva il **post-addestramento**: il **fine-tuning con istruzioni** su esempi di domande e buone risposte, e il **rinforzo dal feedback umano** (RLHF) o da regole scritte, che premia risposte utili, oneste e sicure. Così nasce un assistente. Le conoscenze si fermano alla **data di cutoff** dei dati: per i fatti recenti servono strumenti come la ricerca web.', 'Then comes **post-training**: **instruction fine-tuning** on examples of questions and good answers, and **reinforcement from human feedback** (RLHF) or from written rules, which rewards helpful, honest and safe answers. That is how an assistant is born. Knowledge stops at the data’s **cutoff date**: recent facts need tools such as web search.'),
        ], [
            Q('a1', L('Che cosa impara il modello nel pre-addestramento?', 'What does the model learn in pre-training?'), [L('A prevedere il token successivo su enormi testi', 'To predict the next token over huge texts'), L('A rispondere solo in italiano', 'To answer only in Italian'), L('A navigare sul web', 'To browse the web'), L('A disegnare immagini', 'To draw pictures')], 0, L('La fase più costosa.', 'The most expensive phase.')),
            Q('a2', L('A che cosa serve l’RLHF?', 'What is RLHF for?'), [L('Premiare risposte utili e sicure', 'Rewarding helpful and safe answers'), L('Rendere il modello più leggero', 'Making the model lighter'), L('Aggiungere nuove lingue', 'Adding new languages'), L('Aumentare i token', 'Increasing tokens')], 0, L('Il feedback guida il comportamento.', 'Feedback guides behaviour.')),
            Q('a3', L('Che cos’è la data di cutoff?', 'What is the cutoff date?'), [L('Il limite temporale dei dati di addestramento', 'The time limit of the training data'), L('Il giorno di scadenza del modello', 'The model’s expiry day'), L('L’ora di chiusura dei server', 'The servers’ closing time'), L('La data di nascita dell’azienda', 'The company’s founding date')], 0, L('Dopo, il modello non sa.', 'After it, the model does not know.')),
        ], task('text', L('Metti in ordine le fasi, una per riga numerate da `1.` a `3.`: rinforzo dal feedback, pre-addestramento, fine-tuning con istruzioni.', 'Put the phases in order, one per line numbered `1.` to `3.`: reinforcement from feedback, pre-training, instruction fine-tuning.'), "1. \n2. \n3. ", [re('^1\.\s*(pre)', L('Prima il pre-addestramento', 'Pre-training first')), re('^2\.\s*.*(fine|istruz|instruct)', L('Poi il fine-tuning', 'Then fine-tuning')), re('^3\.\s*.*(rinforz|feedback|reinforc|rlhf)', L('Infine il rinforzo', 'Finally reinforcement'))], '', "1. pre-addestramento\n2. fine-tuning con istruzioni\n3. rinforzo dal feedback (RLHF)"), [
            dOrder(pSort(), [L('Raccolta dei dati', 'Data collection'), L('Pre-addestramento', 'Pre-training'), L('Fine-tuning con istruzioni', 'Instruction fine-tuning'), L('Rinforzo dal feedback', 'Reinforcement from feedback'), L('Rilascio come assistente', 'Release as an assistant')], L('Dalla base all’assistente.', 'From base to assistant.')),
            dFlash(pFlash(), [[L('Un modello base completa testi, non segue istruzioni', 'A base model completes text, it does not follow instructions'), true], [L('Il modello impara i fatti avvenuti dopo il cutoff da solo', 'The model learns facts after the cutoff by itself'), false], [L('Il pre-addestramento è la fase più costosa', 'Pre-training is the most expensive phase'), true], [L('L’RLHF aumenta la dimensione del vocabolario', 'RLHF increases the vocabulary size'), false]], L('Le fasi dell’addestramento.', 'The training phases.')),
        ]),
        lesson('limits', L('Contesto, temperatura e limiti', 'Context, temperature and limits'), [
            P('La **finestra di contesto** è quanti token il modello vede in una volta: istruzioni, conversazione, documenti e risposta. Oltre il limite, il testo più vecchio va tagliato o riassunto. Il modello non ricorda tra una conversazione e l’altra se non gli si ripassa il contesto (o una memoria esterna).', 'The **context window** is how many tokens the model sees at once: instructions, conversation, documents and answer. Beyond the limit, older text must be cut or summarised. The model does not remember between conversations unless the context (or an external memory) is passed back to it.'),
            P('La **temperatura** regola la scelta del token: bassa (vicino a 0) prende quasi sempre il più probabile, risposte stabili e prevedibili; alta mescola di più, risposte varie e creative. Le **allucinazioni** sono risposte sicure ma false: il modello produce testo plausibile, non verifica fatti. Difese: fonti nel contesto (RAG), citazioni, controlli umani.', '**Temperature** controls token choice: low (near 0) almost always takes the most likely one, stable and predictable answers; high mixes more, varied and creative answers. **Hallucinations** are confident but false answers: the model produces plausible text, it does not check facts. Defences: sources in the context (RAG), citations, human review.'),
            Tip('Gli LLM sono deboli dove servono passaggi esatti, come contare lettere o fare calcoli lunghi: per questo i modelli moderni usano strumenti (calcolatrice, codice) o “ragionano” passo passo prima di rispondere.', 'LLMs are weak where exact steps are needed, such as counting letters or long calculations: that is why modern models use tools (calculator, code) or “reason” step by step before answering.'),
        ], [
            Q('l1', L('Che cos’è la finestra di contesto?', 'What is the context window?'), [L('Quanti token il modello vede in una volta', 'How many tokens the model sees at once'), L('La finestra del browser', 'The browser window'), L('Il tempo di risposta', 'The response time'), L('Il numero di utenti', 'The number of users')], 0, L('Istruzioni, chat e risposta insieme.', 'Instructions, chat and answer together.')),
            Q('l2', L('Che effetto ha una temperatura bassa?', 'What does a low temperature do?'), [L('Risposte più stabili e prevedibili', 'More stable and predictable answers'), L('Risposte più creative e varie', 'More creative and varied answers'), L('Risposte più lunghe', 'Longer answers'), L('Risposte in un’altra lingua', 'Answers in another language')], 0, L('Prende quasi sempre il più probabile.', 'It almost always takes the most likely.')),
            Q('l3', L('Che cos’è un’allucinazione?', 'What is a hallucination?'), [L('Una risposta sicura ma falsa', 'A confident but false answer'), L('Un errore di connessione', 'A connection error'), L('Una risposta troppo corta', 'An answer that is too short'), L('Un’immagine generata', 'A generated image')], 0, L('Testo plausibile, non verificato.', 'Plausible, unchecked text.')),
        ], task('text', L('Scegli la temperatura per due compiti, una riga ciascuno: `estrarre dati: ` e `scrivere slogan: `, con `bassa` o `alta` (o `low`/`high`).', 'Pick the temperature for two tasks, one line each: `extract data: ` and `write slogans: `, with `low` or `high`.'), '', [re('(estrarre|extract)[^\n]*:\s*(bassa|low)', L('Bassa per estrarre', 'Low for extracting')), re('(slogan)[^\n]*:\s*(alta|high)', L('Alta per gli slogan', 'High for slogans'))], '', "estrarre dati: bassa\nscrivere slogan: alta"), [
            dMatch(pMatch(), [[L('Finestra di contesto', 'Context window'), L('Token visti in una volta', 'Tokens seen at once')], [L('Temperatura bassa', 'Low temperature'), L('Risposte prevedibili', 'Predictable answers')], [L('Temperatura alta', 'High temperature'), L('Risposte creative', 'Creative answers')], [L('Allucinazione', 'Hallucination'), L('Falso detto con sicurezza', 'Falsehood said confidently')], ['RAG', L('Fonti nel contesto', 'Sources in the context')]], L('Usarli bene.', 'Using them well.')),
            dFlash(pFlash(), [[L('Un LLM può inventare citazioni', 'An LLM can make up citations'), true], [L('Il modello ricorda da solo tutte le chat passate', 'The model remembers all past chats by itself'), false], [L('Contare le lettere è difficile per un LLM', 'Counting letters is hard for an LLM'), true], [L('Temperatura alta significa risposte sempre uguali', 'High temperature means always the same answers'), false]], L('Conoscere i limiti.', 'Knowing the limits.')),
        ]),
        lesson('tools', L('RAG, strumenti e agenti', 'RAG, tools and agents'), [
            P('Un LLM conosce solo ciò che ha visto in addestramento. Con la **RAG** (retrieval-augmented generation) il sistema prima **cerca** documenti pertinenti e li mette nel contesto, poi il modello risponde basandosi su quelli: risposte più aggiornate e con le fonti.', 'An LLM only knows what it saw in training. With **RAG** (retrieval-augmented generation) the system first **searches** relevant documents and puts them in the context, then the model answers based on them: more up-to-date answers, with sources.'),
            P('Con il **tool use** il modello può chiedere di usare strumenti: una calcolatrice, una ricerca web, un’API. Il programma esegue lo strumento e rimanda il risultato al modello. Un **agente** ripete questo ciclo (pensa, agisce, osserva) finché il compito è finito.', 'With **tool use** the model can ask to use tools: a calculator, a web search, an API. The program runs the tool and sends the result back to the model. An **agent** repeats this loop (think, act, observe) until the task is done.'),
            P('Più autonomia vuol dire più rischi: un agente può sbagliare strumento, leggere istruzioni malevole in una pagina (**prompt injection**) o fare azioni irreversibili. Per questo servono permessi limitati e conferme umane sulle azioni importanti.', 'More autonomy means more risk: an agent can pick the wrong tool, read malicious instructions in a page (**prompt injection**) or take irreversible actions. That is why it needs limited permissions and human confirmation for important actions.'),
        ], [
            Q('to1', L('Che cosa aggiunge la RAG?', 'What does RAG add?'), [L('Documenti cercati e messi nel contesto', 'Documents retrieved and put into the context'), L('Più parametri al modello', 'More parameters to the model'), L('Un nuovo addestramento', 'A new training run'), L('Una GPU in più', 'One more GPU')], 0, L('Il modello non cambia, cambia il contesto.', 'The model does not change, the context does.')),
            Q('to2', L('Chi esegue davvero uno strumento nel tool use?', 'Who actually runs a tool in tool use?'), [L('Il programma intorno al modello', 'The program around the model'), L('Il modello stesso', 'The model itself'), L('L’utente a mano, sempre', 'The user by hand, always'), L('Il browser', 'The browser')], 0, L('Il modello chiede, il programma esegue.', 'The model asks, the program runs.')),
            Q('to3', L('Che cos’è la prompt injection?', 'What is prompt injection?'), [L('Istruzioni malevole nascoste nei contenuti letti', 'Malicious instructions hidden in content being read'), L('Un prompt troppo lungo', 'A prompt that is too long'), L('Un errore di battitura', 'A typo'), L('Un tipo di token', 'A type of token')], 0, L('Il modello può scambiarle per ordini.', 'The model may mistake them for orders.')),
        ], task('text', L('Scrivi i tre passi del ciclo di un agente, separati da virgole: `pensa, agisce, osserva`.', 'Write the three steps of an agent’s loop, comma separated: `pensa, agisce, osserva`.'), '', [re('pensa\s*,\s*agisce\s*,\s*osserva', L('Il ciclo è nell’ordine giusto', 'The loop is in the right order'))], '', 'pensa, agisce, osserva'), [
            dOrder(pSort(), [L('La domanda arriva', 'The question arrives'), L('Si cercano i documenti pertinenti', 'Relevant documents are retrieved'), L('I documenti entrano nel contesto', 'The documents enter the context'), L('Il modello risponde citando le fonti', 'The model answers citing sources')], L('Il percorso della RAG.', 'The RAG pipeline.')),
            dFlash(pFlash(), [[L('La RAG non cambia i pesi del modello', 'RAG does not change the model’s weights'), true], [L('Un agente non sbaglia mai strumento', 'An agent never picks the wrong tool'), false], [L('Le azioni irreversibili meritano una conferma umana', 'Irreversible actions deserve human confirmation'), true], [L('Il modello esegue da solo il codice degli strumenti', 'The model runs the tools’ code by itself'), false]], L('Oltre il modello.', 'Beyond the model.')),
        ]),
    ],
];
